# --- safe counting loop: prove div + bounds, recover finite bound by narrowing
counting = [Assign("i", C(0)), Assign("s", C(0)),
    While(lt(V("i"), C(10)), [
        Assign("s", add(V("s"), div(C(100), add(V("i"), C(1))))),
        CheckBounds(V("i"), 10, point="loop"),
        CheckDiv(add(V("i"), C(1)), point="loop"),
        Assign("i", add(V("i"), C(1))),
